/**
 * Captures user feedback and live bug reports generated by the various applications.
 */
export type UserFeedback = {
  /**
   * @format int32
   */
  id?: number;
  /**
   * The device running the application when the feedback was submitted.
   */
  deviceId?: string;
  /**
   * The application being used to submit the feedback.
   *
   * @maxLength 12
   * @minLength 12
   */
  application?: string;
  /**
   * The version of the application used when the feedback was submitted.
   *
   * @maxLength 20
   * @minLength 0
   */
  applicationVersion?: string;
  /**
   * The id of the user who submitted the feedback
   */
  createdBy?: string;
  /**
   * The date and time that the feedback was submitted.
   *
   * @format date-time
   */
  createdOn?: string;
  /**
   * The main content detailing the feedback, which can be stored as Markdown to support rich formatting.
   */
  description?: string;
  /**
   * The type of feedback, such as bug, feature_request, question, comment, or usability issue.
   *
   * @maxLength 12
   * @minLength 12
   */
  category?: string;
  /**
   * Structured data containing technical information: Operating system and version. Browser and version. Device type (e.g., mobile, desktop, tablet). Screen resolution.
   */
  environmentDetails?: string;
  /**
   * The current state of the feedback (new, in_review, in_progress, on_roadmap, completed, closed).
   *
   * @maxLength 12
   * @minLength 12
   */
  status?: string;
  /**
   * The internal priority level (high, medium, low) for stakeholders.
   *
   * @maxLength 12
   * @minLength 12
   */
  priority?: string;
  /**
   * The impact of the issue (critical, major, minor, trivial). Only applicable for bug reports.
   *
   * @maxLength 12
   * @minLength 12
   */
  severity?: string;
  /**
   * Follow up comments from investigators.
   */
  internalNotes?: string;
  /**
   * The id of the user who last updated the record.
   */
  updatedBy?: string;
  /**
   * The timestamp of the time of the last update.
   *
   * @format date-time
   */
  updatedOn?: string;
  /**
   * When the feedback is related to a defect, an optional list of steps that can be used by investgators to reproduce the issue.
   */
  stepsToReproduce?: string;
  /**
   * The date and time, in UTC, that the user feedback was generated from the perspective of the generating application.
   *
   * @format date-time
   */
  occurredOn?: string;
  /**
   * An arbitrary attachment, in raw byte form. For example, an image from a screenshot.
   *
   * @format byte
   */
  attachment?: string;
};

